UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <p>This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have established specialised skills in a technical ICT function such as General Application Support Officer, IT Office Manager. This role enables individuals to carry out moderately complex tasks in specialist fields, working independently, as part of a team or leading deliverables with others. They may apply their skills across a wide range of industries, business functions and departments, or as a business owner (sole trader/contractor).</p> <p>This qualification requires skills such as: advance networking, advanced programming, backend web development, business analysis, cloud architecture, cloud engineering, cyber security, game programming, game art and design, system administration, system analysis, etc.</p> </div><h4>Who Should Undertake This Qualification</h4><div> <p>This qualification is aimed at students who would like to enhance their skills and knowledge to create further educational and employment opportunities for themselves.</p> <p>It is also anticipated that this qualification may be of interest to those overseas students who wish to enter the business or management profession or who are seeking to move to the profession from another sector.</p> </div><h4>Course Subjects</h4><div> <p>Total number of units = 20</p> <p>There are 6 core units for this qualification, plus 14 elective units</p> <table width="642"> <tbody> <tr> <td width="491">Unit Code &amp; Title</td> <td width="151">Core/Elective</td> </tr> <tr> <td width="491">BSBCRT512 – Originate and develop concepts</td> <td width="151">C</td> </tr> <tr> <td width="491">BSBXCS402 – Promote workplace cyber security awareness and best practices</td> <td width="151">C</td> </tr> <tr> <td width="491">BSBXTW401 – Lead and facilitate a team</td> <td width="151">C</td> </tr> <tr> <td width="491">ICTICT517 – Match ICT needs with the strategic direction of the organisation</td> <td width="151">C</td> </tr> <tr> <td width="491">ICTICT532 – Apply IP, ethics and privacy policies in ICT environments</td> <td width="151">C</td> </tr> <tr> <td width="491">ICTSAS527 – Manage client problems</td> <td width="151">C</td> </tr> <tr> <td width="491">ICTSAD508 – Develop technical requirements for business solutions</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTCYS407 – Gather, analyse and interpret threat data</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTCYS610 – Protect critical infrastructure for organisations</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTCYS613 – Utilise design methodologies for security architecture</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTSAS524 – Develop, implement and evaluate an incident response plan</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTSAS526 – Review and update disaster recovery and contingency plans</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTICT443 – Work collaboratively in the ICT industry</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTSAD509 – Produce ICT feasibility reports</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTICT518 – Research and review hardware technology options for organisations</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTICT523 – Gather data to identify business requirements</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTICT526 – Verify client business requirements</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTWEB518 – Build a document using extensible markup language</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTPMG505 – Manage ICT projects</td> <td width="151">E</td> </tr> <tr> <td width="491">ICTWEB527 – Research and apply emerging web technology trends</td> <td width="151">E</td> </tr> </tbody> </table> </div>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = 12400,
    enrolment_fee = 250,
    materials_fee = 150,
    entry_requirements = '<h4>Entry Requirements</h4><div> <ul> <li>For admission into this course, all students must be of the age of 18 years or over at the time of applying for admission. Entry into this course requires IELTS band score of 5.5 or equivalent in line with Department of Home Affairs regulations.</li> <li>Satisfactory completion of studies in applicant’s home country equivalent to an Australian Year 12 qualification is required for entry into this course.</li> </ul> <p>Mature age students will also be considered without the minimum education requirements but with relevant work experience within chosen area of study and a demonstrated capacity to meet course requirements. Please note that the minimum English Language Level requirements apply to all students.</p> </div><h4>Language, Literacy and Numeracy</h4><div> <p>The students will also be required to undertake an LLN test to identify if they will require additional learning support and if the identified level of additional support is within RSB capabilities to deliver. Based on the group of students that this course is designed for all are expected to have high- level of LLN capabilities.</p> </div>',
    apply_form = 'https://rsb.edu.au/services/ict50220-diploma-of-information-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '112219E';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <p>This qualification reflects the trade qualified role of a bricklayer, blocklayer or paver who may have responsibility for undertaking heritage bricklaying, refractory bricklaying, bricklaying, blocklaying and paving work in residential, industrial and commercial contexts, in both existing and new constructions.</p> <p>This qualification applies to job titles such as bricklayer, blocklayer and paver. The bricklaying, blocklaying and paving industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or closely simulated workplace environment and this qualification requires all units of competency to be delivered and assessed in this context.</p> </div><h4>Who Should Undertake This Qualification</h4><div> <p>This qualification is aimed at targeting overseas students, who are:</p> <p>• seeking to pursue or further a career in bricklaying, block laying and paving;<br/> • seeking to enter a new industry sector;<br/> • seeking a pathway to higher level qualifications.</p> <p>Characteristics of the target group are as follows:</p> <p>Students will be from a range of countries and may be living in Australia for the first time or may have been here in the recent or more distant past.<br/> Many will speak English as a second language, although an entry level has been set to ensure students are able to complete course work. Students are expected to typically fall into the age range of 18 – 35 as people still establishing or changing careers. Credit and/or RPL can be provided for those with existing skills and<br/> knowledge allowing such students to complete the course in a shorter timeframe.</p> </div><h4>Course Subjects</h4><div> <p>Total number of units = 28</p> <p>There are 20 core units for this qualification, plus 8 elective units.</p> <table> <tbody> <tr> <td>Unit Code &amp; Title</td> <td>Core/Elective</td> </tr> <tr> <td>CPCCBL2001* – Handle and prepare bricklaying and blocklaying materials</td> <td>C</td> </tr> <tr> <td>CPCCBL2002* – Use bricklaying and blocklaying tools and equipment</td> <td>C</td> </tr> <tr> <td>CPCCBL3002* – Carry out masonry veneer construction</td> <td>C</td> </tr> <tr> <td>CPCCBL3003* – Carry out cavity brick construction</td> <td>C</td> </tr> <tr> <td>CPCCBL3005* – Lay masonry walls and corners</td> <td>C</td> </tr> <tr> <td>CPCCBL3006* – Lay multi-thickness walls and piers</td> <td>C</td> </tr> <tr> <td>CPCCBL3009* – Install flashings and damp-proof course</td> <td>C</td> </tr> <tr> <td>CPCCBL3010* – Construct masonry arches</td> <td>C</td> </tr> <tr> <td>CPCCBL3011* – Construct curved walls</td> <td>C</td> </tr> <tr> <td>CPCCBL3013* – Construct masonry structural systems</td> <td>C</td> </tr> <tr> <td>CPCCCA3002* – Carry out setting out</td> <td>C</td> </tr> <tr> <td>CPCCCM2006 – Apply basic levelling procedures</td> <td>C</td> </tr> <tr> <td>CPCCCM2008* – Erect and dismantle restricted height scaffolding</td> <td>C</td> </tr> <tr> <td>CPCCCM2012* – Work safely at heights</td> <td>C</td> </tr> <tr> <td>CPCCOM1012 – Work effectively and sustainably in the construction industry</td> <td>C</td> </tr> <tr> <td>CPCCOM1013 – Plan and organise work</td> <td>C</td> </tr> <tr> <td>CPCCOM1014 – Conduct workplace communication</td> <td>C</td> </tr> <tr> <td>CPCCOM1015 – Carry out measurements and calculations</td> <td>C</td> </tr> <tr> <td>CPCCOM2001* – Read and interpret plans and specifications</td> <td>C</td> </tr> <tr> <td>CPCCWHS2001 – Apply WHS requirements, policies and procedures in the construction industry</td> <td>C</td> </tr> <tr> <td>CPCWHS1001 – CPCWHS1001 Prepare to work safely in the construction industry (Imported)</td> <td>E</td> </tr> <tr> <td>CPCCBL3016* – Construct battered masonry walls and piers</td> <td>E</td> </tr> <tr> <td>CPCCCO2013* – Carry out concreting to simple forms</td> <td>E</td> </tr> <tr> <td>CPCCSF2004* – Place and fix reinforcement materials</td> <td>E</td> </tr> <tr> <td>CPCCPA3002* – Lay segmental paving (Group C)</td> <td>E</td> </tr> <tr> <td>CPCCPA3003* – Cut segmental paving (Group C)</td> <td>E</td> </tr> <tr> <td>CPCCBL3001* – Lay paving (General)</td> <td>E</td> </tr> <tr> <td>CPCCCM2009* – Carry out basic demolition (General)</td> <td>E</td> </tr> </tbody> </table> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 34000,
    enrolment_fee = 250,
    materials_fee = 300,
    entry_requirements = '<h4>Entry Requirements</h4><div> <p>RSB has the following entry requirements where International students must:</p> <p>• be at least 18 years of age and have completed 12 or equivalent;<br/> • participate in a course entry interview to determine suitability for the course and student needs;<br/> • have an IELTS* score of 5.5 (test results must be no more than 2 years old).</p> <p> </p> <p>English language competence can also be demonstrated through documented evidence of any of the following:</p> <p>• educated for 5 years in an English-speaking country; or<br/> • successful completion of an English Placement Test.</p> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 5.5.</p> </div><h4>Language, Literacy and Numeracy</h4><div> <p>The students will also be required to undertake an LLN test to identify if they will require additional learning support and if the identified level of additional support is within RSB capabilities to deliver. Based on the group of students that this course is designed for all are expected to have high- level of LLN capabilities.</p> </div>',
    apply_form = 'https://rsb.edu.au/services/cpc33020-certificate-iii-in-bricklaying-and-blocklaying-2/',
    updated_at = NOW()
WHERE cricos_course_code = '112916B';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <p>This is a trade qualification for carpenters in residential and commercial workplaces. It includes setting out, manufacturing, constructing, assembling, installing and repairing products made using timber and non-timber materials. This qualification applies to job titles such as commercial carpenter, residential carpenter and formwork carpenter.</p> </div><h4>Who Should Undertake This Qualification</h4><div> <p>This qualification is aimed at targeting overseas students, who are:</p> <ul> <li>seeking to pursue or further a career in carpentry;</li> <li>seeking to enter a new industry sector;</li> <li>seeking a pathway to higher level qualifications.</li> </ul> <p>Characteristics of the target group are as follows:</p> <ul> <li>Students will be from a range of countries and may be living in Australia for the first time or may have been here in the recent or more distant past.</li> <li>Many will speak English as a second language, although an entry level has been set to ensure students are able to complete course work.</li> <li>Students are expected to typically fall into the age range of 18 – 35 as people are still establishing or changing careers.</li> <li>Credit and/or RPL can be provided for those with existing skills and knowledge allowing such students to complete the course in a shorter time frame.</li> </ul> </div><h4>Course Subjects</h4><div> <p>Total number of units = 34</p> <p>There are 27 core units for this qualification, plus 7 elective units.</p> <table> <tbody> <tr> <td>Unit Code &amp; Title</td> <td>Core/Elective</td> </tr> <tr> <td>CPCCCA2002 – Use carpentry tools and equipment</td> <td>C</td> </tr> <tr> <td>CPCCCA2011 – Handle carpentry materials</td> <td>C</td> </tr> <tr> <td>CPCCCA3001 – Carry out general demolition of minor building structures</td> <td>C</td> </tr> <tr> <td>CPCCCA3002 – Carry out setting out</td> <td>C</td> </tr> <tr> <td>CPCCCA3003 – Install flooring systems</td> <td>C</td> </tr> <tr> <td>CPCCCA3004 – Construct and erect wall frames</td> <td>C</td> </tr> <tr> <td>CPCCCA3005 – Construct ceiling frames</td> <td>C</td> </tr> <tr> <td>CPCCCA3006 – Erect roof trusses</td> <td>C</td> </tr> <tr> <td>CPCCCA3007 – Construct pitched roofs</td> <td>C</td> </tr> <tr> <td>CPCCCA3008 – Construct eaves</td> <td>C</td> </tr> <tr> <td>CPCCCA3010 – Install windows and doors</td> <td>C</td> </tr> <tr> <td>CPCCCA3016 – Construct, assemble and install timber external stairs</td> <td>C</td> </tr> <tr> <td>CPCCCA3017 – Install exterior cladding</td> <td>C</td> </tr> <tr> <td>CPCCCA3024 – Install lining, panelling and moulding</td> <td>C</td> </tr> <tr> <td>CPCCCA3025 – Read and interpret plans, specifications and drawings for carpentry work</td> <td>C</td> </tr> <tr> <td>CPCCCA3028 – Erect and dismantle formwork for footings and slabs on ground</td> <td>C</td> </tr> <tr> <td>CPCCCM2006 – Apply basic levelling procedures</td> <td>C</td> </tr> <tr> <td>CPCCCM2008 – Erect and dismantle restricted height scaffolding</td> <td>C</td> </tr> <tr> <td>CPCCCM2012 – Work safely at heights</td> <td>C</td> </tr> <tr> <td>CPCCCO2013 – Carry out concreting to simple forms</td> <td>C</td> </tr> <tr> <td>CPCCOM1012 – Work effectively and sustainably in the construction industry</td> <td>C</td> </tr> <tr> <td>CPCCOM1014 – Conduct workplace communication</td> <td>C</td> </tr> <tr> <td>CPCCOM1015 – Carry out measurements and calculations</td> <td>C</td> </tr> <tr> <td>CPCCOM3001 – Perform construction calculations to determine carpentry material requirements</td> <td>C</td> </tr> <tr> <td>CPCCOM3006 – Carry out levelling operations</td> <td>C</td> </tr> <tr> <td>CPCCWHS2001 – Apply WHS requirements, policies and procedures in the construction industry</td> <td>C</td> </tr> <tr> <td>CPCWHS3001– Identify construction work hazards and select risk control strategies</td> <td>C</td> </tr> <tr> <td>CPCCCA3012 – Frame and fit wet area fixtures</td> <td>E</td> </tr> <tr> <td>CPCCCA3014 – Construct and install bulkheads</td> <td>E</td> </tr> <tr> <td>CPCCCM2002 – Carry out hand excavation</td> <td>E</td> </tr> <tr> <td>CPCCJN3003 – Manufacture components for doors, windows and frames</td> <td>E</td> </tr> <tr> <td>CPCCSF2004* – Place and fix reinforcement materials</td> <td>E</td> </tr> <tr> <td>CPCCCM3005 – Calculate costs of construction work</td> <td>E</td> </tr> <tr> <td>CPCCWHS1001 – Prepare to work safely in the construction industry (Imported)</td> <td>E</td> </tr> </tbody> </table> </div>',
    total_course_duration = '52 weeks',
