UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <p><span>This qualification reflects the role of building professionals such as builder, general foreperson, building inspector, This individual knowledge of structural principles, risk and financial management, estimating, preparing and administering building and construction contracts, selecting contractors, overseeing the work and its quality and managing construction work in building projects including residential and commercial with the following limitations:</span></p> <ol> <li><span>Residential construction limited to National Construction Code Class 1 and 10 buildings to a maximum of 3 storeys.</span></li> <li><span>Commercial construction limited to National Construction Code Class 2 to 9 buildings, Type C and B construction.</span></li> </ol> </div><h4>Who Should Undertake This Qualification</h4><div> <p>Target groups for the <strong>CPC50220 Diploma of Building and Construction (Building) </strong>are international students who are seeking to pursue a career in the following professions:</p> <ul> <li>Builder</li> <li>General Foreperson</li> <li>Building Inspector</li> </ul> <p>The characteristics of the target group are as follows:</p> <ul> <li>Students will be from a range of countries and may be living in Australia for the first time or may have been here in the recent or more distant past.</li> <li>Many will speak English as a second language, although an entry level has been set to ensure students are able to complete course work.</li> <li>Students are expected to typically fall into the age range of 18 – 35 as people still establishing or changing careers.</li> </ul> <p>Credit and/or RPL can be provided for those with existing skills and knowledge allowing such students to complete the course in a shorter timeframe.</p> </div><h4>Course Subjects</h4><div> <p>Total number of units = 27</p> <p>There are 24 core units for this qualification, plus 3 elective units.</p> <table> <tbody> <tr> <td width="482">Unit Code &amp; Title</td> <td width="119">Core/Elective</td> </tr> <tr> <td width="482">BSBOPS504 – Manage business risk</td> <td width="119">C</td> </tr> <tr> <td width="482">BSBWHS513 – Lead WHS risk management</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4001 – Apply building codes and standards to the construction process for Class 1 and 10 buildings</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4003 – Select, prepare, and administer a construction contract</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4004 – Identify and produce estimated costs for building and construction projects</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4005 – Produce labour and material schedules for ordering</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4008 – Supervise site communication and administration processes for building and construction projects</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4009 – Apply legal requirements to building and construction projects</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4010*– Apply structural principles to residential and commercial constructions</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4012 – Read and interpret plans and specifications</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4013 – Prepare and evaluate tender documentation</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4014 – Prepare simple building sketches and drawings</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4018 – Apply site surveys and set-out procedures to building and construction projects</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC4053 – Apply building codes and standards to the construction process for Class 2 to 9, Type C buildings</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5001 – Apply building codes and standards to the construction process for Type B construction</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5002 – Monitor costing systems on complex building and construction projects</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5003 – Supervise the planning of onsite building and construction work</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5005 – Select and manage building and construction contractors</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5007 – Administer the legal obligations of a building and construction contractor</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5010 – Manage construction work</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5011 – Manage environmental management practices and processes in building and construction</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5013 – Manage professional technical and legal reports on building and construction projects</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5018* – Apply structural principles to the construction of buildings up to 3 storeys</td> <td width="119">C</td> </tr> <tr> <td width="482">CPCCBC5019 – Manage building and construction business finance</td> <td width="119">C</td> </tr> <tr> <td width="482">BSBPMG538 – Manage project stakeholder engagement</td> <td width="119">E</td> </tr> <tr> <td width="482">BSBPMG532 – Manage project quality</td> <td width="119">E</td> </tr> <tr> <td width="482">BSBPMG535 – Manage project information and communication</td> <td width="119">E</td> </tr> </tbody> </table> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 20000,
    enrolment_fee = 250,
    materials_fee = 95,
    entry_requirements = '<h4>Entry Requirements</h4><div> <p>International students must:</p> <ul> <li>Be over 18 years of age and have completed Year 12 or equivalent.</li> <li>Participate in a course entry interview to determine suitability for the course and student needs.</li> <li>Have an IELTS* score of 5.5 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul> <li>Educated for 5 years in an English-speaking country; or</li> <li>Completed at least 6 months of a Certificate IV level course in an Australian RTO; or</li> <li>Successful completion of an English Placement Test</li> </ul> </li> </ul> <ul> <li></li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 5.5.</p> </div><h4>Language, Literacy and Numeracy</h4><div> <p>The students will also be required to undertake an LLN test to identify if they will require additional learning support and if the identified level of additional support is within RSB capabilities to deliver. Based on the group of students that this course is designed for all are expected to have high- level of LLN capabilities.</p> </div>',
    apply_form = 'https://rsb.edu.au/services/cpc50220-diploma-of-building-and-construction-building/',
    updated_at = NOW()
WHERE cricos_course_code = '112918M';
